Arguments:
$ErrorActionPreference='Stop'
$obj='benchmarks/SomeEngine.ECS.Relations.Benchmarks/obj/Release/net10.0/win-x64/native/SomeEngine.ECS.Relations.Benchmarks.obj'
$llvm='C:/Program Files/LLVM/bin/llvm-objdump.exe'
Get-Item -LiteralPath $obj | Select-Object Length,LastWriteTimeUtc | Format-List
Write-Output '=== SOURCE r16 RelationQuery ==='
git show 92d8b230:src/SomeEngine.ECS.Relations/RelationQuery.cs | Select-Object -First 130
$symbols=@(& $llvm --syms $obj | Where-Object {$_ -match '\(sec\s+2\).* 0x[0-9a-f]+ '})
$chosen=@($symbols|Where-Object {
 $_ -match 'HandwrittenDefaultSide__Query$|HandwrittenDefaultPairs__Enumerate<' -or
 ($_ -match 'RelationArraySide_1<.*ComponentPairsWithin_3<.*DefaultContacts.*__Query$') -or
 ($_ -match 'RelationQuery_2<.*ComponentPairsWithin_3<.*DefaultContacts.*__Enumerate(Single|BoundQuery|Query)<')
})
Write-Output '=== DEFAULT OUTER SYMBOLS ==='
$symbols|Where-Object {
 $_ -match 'RelationQuery_2<.*ComponentPairsWithin_3<.*DefaultContacts.*__Enumerate(Single|BoundQuery|Queries|Query)<'
}|ForEach-Object {Write-Output $_}
foreach($line in $chosen){
 $name=$line -replace '^.* 0x[0-9a-f]+ ',''
 Write-Output ('=== SYMBOL '+$line+' ===')
 & $llvm -d -r --no-show-raw-insn ('--disassemble-symbols='+$name) $obj | ForEach-Object {
  if($_ -match '^\s*([0-9a-f]+):\s+(callq|jmp)\s+(\S+)\s+<(.*)>$'){
   '  '+$Matches[1]+': '+$Matches[2]+' '+$Matches[3]+' '+($Matches[4] -replace '<.*>','<...>')
  }else{$_ -replace '<.*>','<...>'}
 }
}
